fn reverse(a: Vec<char>) -> Vec<char> {
    // We can consume `a` and use its into_iter() to get ownership of each char,
    // then .rev() to reverse the iterator, and finally collect into a Vec<char>.
    a.into_iter().rev().collect()
}

// Example usage and a simple test
fn main() {
    let input: Vec<char> = vec!['h', 'e', 'l', 'l', 'o'];
    let output = reverse(input.clone());
    assert_eq!(output, vec!['o', 'l', 'l', 'e', 'h']);
    println!("Input  : {:?}", input);
    println!("Reversed: {:?}", output);
}